if 'calculate_sum' not in globals():
    raise AssertionError('Task 1: calculate_sum function not defined')

if not callable(globals()['calculate_sum']):
    raise AssertionError('Task 1: calculate_sum should be a function')

calc_sum = globals()['calculate_sum']

# Test with different numbers of arguments
if calc_sum(10, 20) != 30:
    raise AssertionError('Task 1: calculate_sum(10, 20) should return 30')

if calc_sum(5, 10, 15) != 30:
    raise AssertionError('Task 1: calculate_sum(5, 10, 15) should return 30')

if calc_sum(100) != 100:
    raise AssertionError('Task 1: calculate_sum(100) should return 100')

if calc_sum() != 0:
    raise AssertionError('Task 1: calculate_sum() with no arguments should return 0')

if calc_sum(10, 20, 30, 40) != 100:
    raise AssertionError('Task 1: calculate_sum(10, 20, 30, 40) should return 100')

print('TEST_PASSED')

if 'build_profile' not in globals():
    raise AssertionError('Task 2: build_profile function not defined')

if not callable(globals()['build_profile']):
    raise AssertionError('Task 2: build_profile should be a function')

build = globals()['build_profile']

result1 = build(name='Alex', age=30)
if not isinstance(result1, dict):
    raise AssertionError('Task 2: build_profile should return a dictionary')
if result1.get('name') != 'Alex' or result1.get('age') != 30:
    raise AssertionError('Task 2: build_profile should contain all keyword arguments')

result2 = build(username='coder', level=5, verified=True)
if len(result2) != 3:
    raise AssertionError('Task 2: build_profile should contain exactly the arguments provided')

print('TEST_PASSED')

